SELECT t1.PSN_NAME AS `基金经理`, t2.REPORT_DATE AS `报告期`, ROUND(SUM(t2.NET_VALUE) / 100000000, 2) AS `在管总规模(亿元)` FROM FUND_AND_MANAGER_MAPPING t1 INNER JOIN FUND_ASSET_ALLOCATION t2 ON t1.FUND_HCODE = t2.FUND_HCODE WHERE t1.PSN_NAME = '刘彦春' AND t1.BEGIN_DATE <= '2024-12-31' AND (t1.END_DATE IS NULL OR t1.END_DATE >= '2024-12-31') AND t1.HISVALID = 1 AND t2.REPORT_DATE = '2024-12-31' AND t2.HISVALID = 1 AND t2.NET_VALUE IS NOT NULL GROUP BY t1.PSN_NAME, t2.REPORT_DATE;
200
